-- Package library (ADR 047, docs/SUPPLIER_OPERATIONS.md): ready-made transfers,
-- sightseeing and activities for popular destinations, kept by the Idea Holiday
-- admin. A supplier adds entries to its own private rate sheet (069), where they
-- become ordinary services it can edit; the library itself is never priced or sold.
--
-- Prices are EXAMPLES the supplier must check: per vehicle for Sedan (4 seats),
-- Innova (6) and Tempo Traveller (12), or per adult and child for an activity.
-- Adding an entry copies them into one season starting that day.

CREATE TABLE IF NOT EXISTS package_library_items (
  id TEXT PRIMARY KEY,
  region TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('TRANSFER', 'SIGHTSEEING', 'ACTIVITY')),
  name TEXT NOT NULL,
  city TEXT,
  from_place TEXT,
  to_place TEXT,
  distance_km INTEGER,
  duration_hours REAL,
  day_title TEXT,
  day_description TEXT,
  sedan_inr INTEGER CHECK (sedan_inr >= 0),
  innova_inr INTEGER CHECK (innova_inr >= 0),
  tempo_inr INTEGER CHECK (tempo_inr >= 0),
  adult_inr INTEGER CHECK (adult_inr >= 0),
  child_inr INTEGER CHECK (child_inr >= 0),
  sort_order INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'INACTIVE')),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_package_library_items_region ON package_library_items(status, region, sort_order);

-- Which library entry a supplier's service came from, so it is not added twice.
ALTER TABLE supplier_services ADD COLUMN IF NOT EXISTS library_item_id TEXT;

-- The starter library: Golden Triangle, Uttar Pradesh, Goa, Kerala, Himachal Pradesh,
-- Jammu & Kashmir, Leh Ladakh, Rajasthan and Uttarakhand. Entry fees are for Indian nationals.

-- @down
ALTER TABLE supplier_services DROP COLUMN library_item_id;
DROP INDEX IF EXISTS idx_package_library_items_region;
DROP TABLE IF EXISTS package_library_items;
